import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture as textureSampler, uv as uvSampler } from 'three/tsl';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();

  const spec = config.intent?.visualSpec ?? {};
  const colors = spec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config.textContent ?? spec.textContent ?? [];

  const width = 3.84;
  const height = 2.4;

  const geometry = new THREE.PlaneGeometry(width, height);
  const material = new MeshBasicNodeMaterial({
    color: colors.surface,
    side: THREE.FrontSide,
  });

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'heroHeadlineSurface';
  group.add(plane);

  const textGroup = new THREE.Group();
  textGroup.position.z = 0.02;

  for (const item of items) {
    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize ?? (role === 'body' ? 31 : 68);
    const align = item.align ?? 'left';

    const text = ctx.fontAtlas.createText(String(item.text ?? ''), {
      fontSize,
      color: colors.paper,
      align,
    });

    text.position.set(-width / 2 + 0.2, height / 2 - 0.35, 0);
    textGroup.add(text);
  }

  group.add(textGroup);

  let loadedTexture = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (!tex) return;
      loadedTexture = tex;
      tex.colorSpace = THREE.SRGBColorSpace;

      material.colorNode = textureSampler(tex, uvSampler());
      material.needsUpdate = true;
    });
  }

  const timelines = [];

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((tl) => {
      try {
        tl?.kill();
      } catch (e) {}
    });

    textGroup.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }

    material.dispose();
    geometry.dispose();
    group.clear();
  };

  return group;
}
